def check_exam_eligibility(attendance_pct, has_medical_cert):
    if attendance_pct >= 75.0:
        return {'status': 'Eligible', 'fee': 0}
    elif 65.0 <= attendance_pct < 75.0 and has_medical_cert:
        return {'status': 'Condonation Granted', 'fee': 1200}
    else:
        return {'status': 'Debarred', 'fee': 0}

